using System.IO.Abstractions;

namespace MyApp.Services;

/// <summary>
/// Wrapper around <see cref="IFileSystem"/> providing higher-level file operations.
/// </summary>
public class FileSystemWrapper(IFileSystem fileSystem) : IFileSystemWrapper
{
    public IFileSystem FileSystem => fileSystem;

    public string ReadAllText(string path)
    {
        if (!fileSystem.File.Exists(path))
        {
            throw new FileNotFoundException($"File not found: {path}", path);
        }

        return fileSystem.File.ReadAllText(path);
    }

    public byte[] ReadAllBytes(string path)
    {
        if (!fileSystem.File.Exists(path))
        {
            throw new FileNotFoundException($"File not found: {path}", path);
        }

        return fileSystem.File.ReadAllBytes(path);
    }

    public string[] ReadAllLines(string path)
    {
        if (!fileSystem.File.Exists(path))
        {
            throw new FileNotFoundException($"File not found: {path}", path);
        }

        return fileSystem.File.ReadAllLines(path);
    }

    public void WriteAllText(string path, string contents)
    {
        EnsureDirectoryExists(fileSystem.Path.GetDirectoryName(path));
        fileSystem.File.WriteAllText(path, contents);
    }

    public void WriteAllBytes(string path, byte[] bytes)
    {
        EnsureDirectoryExists(fileSystem.Path.GetDirectoryName(path));
        fileSystem.File.WriteAllBytes(path, bytes);
    }

    public void WriteAllLines(string path, IEnumerable<string> lines)
    {
        EnsureDirectoryExists(fileSystem.Path.GetDirectoryName(path));
        fileSystem.File.WriteAllLines(path, lines);
    }

    public Stream OpenRead(string path)
    {
        if (!fileSystem.File.Exists(path))
        {
            throw new FileNotFoundException($"File not found: {path}", path);
        }

        return fileSystem.File.OpenRead(path);
    }

    public Stream Create(string path)
    {
        EnsureDirectoryExists(fileSystem.Path.GetDirectoryName(path));
        return fileSystem.File.Create(path);
    }

    public bool FileExists(string path) => fileSystem.File.Exists(path);

    public bool DirectoryExists(string path) => fileSystem.Directory.Exists(path);

    public void EnsureDirectoryExists(string? path)
    {
        if (!string.IsNullOrEmpty(path) && !fileSystem.Directory.Exists(path))
        {
            fileSystem.Directory.CreateDirectory(path);
        }
    }

    public void DeleteFile(string path)
    {
        if (fileSystem.File.Exists(path))
        {
            fileSystem.File.Delete(path);
        }
    }

    public void DeleteDirectory(string path, bool recursive = false)
    {
        if (fileSystem.Directory.Exists(path))
        {
            fileSystem.Directory.Delete(path, recursive);
        }
    }

    public void CopyFile(string sourcePath, string destinationPath, bool overwrite = false)
    {
        EnsureDirectoryExists(fileSystem.Path.GetDirectoryName(destinationPath));
        fileSystem.File.Copy(sourcePath, destinationPath, overwrite);
    }

    public void MoveFile(string sourcePath, string destinationPath)
    {
        EnsureDirectoryExists(fileSystem.Path.GetDirectoryName(destinationPath));
        fileSystem.File.Move(sourcePath, destinationPath);
    }

    public IEnumerable<string> EnumerateFiles(string path, string searchPattern = "*", SearchOption searchOption = SearchOption.TopDirectoryOnly)
    {
        if (!fileSystem.Directory.Exists(path))
        {
            return Enumerable.Empty<string>();
        }

        return fileSystem.Directory.EnumerateFiles(path, searchPattern, searchOption);
    }

    public IEnumerable<string> EnumerateDirectories(string path, string searchPattern = "*", SearchOption searchOption = SearchOption.TopDirectoryOnly)
    {
        if (!fileSystem.Directory.Exists(path))
        {
            return Enumerable.Empty<string>();
        }

        return fileSystem.Directory.EnumerateDirectories(path, searchPattern, searchOption);
    }

    public string GetFullPath(string path) => fileSystem.Path.GetFullPath(path);

    public string Combine(params string[] paths) => fileSystem.Path.Combine(paths);
}

